import { useId, useMemo } from 'react'
import {
  EXPRESSIONS,
  PALETTES,
  shapeFor,
  type Blush,
  type BodyForm,
  type Crown as CrownKind,
  type Eyes,
  type Growth,
  type Lineage,
  type Mood,
  type Mouth,
  type StageShape,
} from './model'
import './temu.css'

/**
 * Temu — one parametric SVG for every stage (docs/ART_BIBLE.md).
 *
 * The crest is the identity: two arcs rising from opposite sides that cross at
 * a single point. Below the crossing they are two things; above it, one shape.
 * Everything else — body, face, limbs — is proportional to `bodyH`, so adding a
 * stage means adding a row of numbers, never drawing a new character.
 */

const CANVAS = 200
/**
 * Cheeks are always warm rose, whatever the lineage.
 *
 * They used to take the palette's `accent`, which is a *contrast* colour — on
 * teduh that is teal, so the shy face came out with two green-blue streaks
 * under the eyes and read as crying rather than blushing.
 */
const BLUSH = '#F2708C'
/** Ground anchor. Identical in every stage and frame, which is what stops jitter. */
const GROUND_Y = 172

export interface TemuProps {
  growth: Growth
  lineage?: Lineage
  mood?: Mood
  size?: number
  /** Both halves of the day's pulse — drives the chest mark, not the face. */
  pulse?: { a: boolean; b: boolean }
  /** Big one-shot animation for a milestone. */
  celebrate?: boolean
  className?: string
  /** Screen-reader name. Omit inside a card that already names it. */
  label?: string
}

export function Temu({
  growth,
  lineage = 'awal',
  mood = 'calm',
  size = 200,
  pulse,
  celebrate = false,
  className,
  label,
}: TemuProps) {
  const uid = useId().replace(/:/g, '')
  const s = useMemo(() => shapeFor(growth), [growth])
  const p = PALETTES[lineage]
  const face = EXPRESSIONS[mood]

  // Geometry, all derived from bodyH so proportions hold at every stage.
  const h = s.bodyH
  const w = h * s.bodyW
  const cx = CANVAS / 2
  const bottom = GROUND_Y - s.leg
  const top = bottom - h
  const cy = top + h / 2

  // The reference set's charm comes from a large light plate carrying small
  // features. Everything on the face is sized to the plate, not to the body.
  const faceCy = top + h * s.faceY
  const faceRx = (w * s.facePlate) / 2
  const faceRy = faceRx * 0.94
  const eyeR = Math.max(1.9, faceRx * 0.185)
  const eyeDx = faceRx * 0.42
  const eyeCy = faceCy - faceRy * 0.12
  const mouthCy = faceCy + faceRy * 0.34

  const isSpark = growth.stage.index === 0

  /**
   * Fit the whole figure inside the canvas, anchored to the ground.
   *
   * The late stages used to draw their crest above y=0 — `abadi` reached −24 —
   * so the fan was cut off and every big stage looked like the same body with a
   * bump on top. Clamping here instead of shrinking the numbers keeps growth
   * monotonic (small stages are untouched) and means a future stage can never
   * silently lose its head.
   */
  const figH = s.leg + h + Math.max(0, s.crest - h * 0.05)
  const fit = Math.min(1, (GROUND_Y - 12) / figH)

  return (
    <svg
      className={['temu', celebrate ? 'temu--celebrate' : '', className].filter(Boolean).join(' ')}
      width={size}
      height={size}
      viewBox={`0 0 ${CANVAS} ${CANVAS}`}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      style={{ overflow: 'visible' }}
    >
      <defs>
        {/* Art bible §3: light always from upper-left, 200°, five stops max. */}
        <linearGradient id={`${uid}-body`} x1="18%" y1="0%" x2="82%" y2="100%">
          <stop offset="0%" stopColor={p.highlight} />
          <stop offset="55%" stopColor={p.body} />
          <stop offset="100%" stopColor={p.deep} />
        </linearGradient>
        <linearGradient id={`${uid}-crest`} x1="0%" y1="100%" x2="100%" y2="0%">
          <stop offset="0%" stopColor={p.body} />
          <stop offset="100%" stopColor={p.highlight} />
        </linearGradient>
        {/* The plate used to be a flat ellipse of near-white, which read as a
            mask stuck onto the body rather than a face. Fading the last 18%
            into nothing lets it sit *in* the body. */}
        <radialGradient id={`${uid}-face`}>
          <stop offset="0%" stopColor={p.face} />
          <stop offset="82%" stopColor={p.face} />
          <stop offset="100%" stopColor={p.face} stopOpacity="0" />
        </radialGradient>
        <radialGradient id={`${uid}-glow`}>
          <stop offset="0%" stopColor={p.body} stopOpacity="0.55" />
          <stop offset="70%" stopColor={p.body} stopOpacity="0.12" />
          <stop offset="100%" stopColor={p.body} stopOpacity="0" />
        </radialGradient>
      </defs>

      {/* Aura — late stages only, and never bright enough to compete with the face. */}
      {s.glow > 0.12 && (
        <circle
          className="temu__glow"
          cx={cx}
          cy={cy}
          r={w * 1.15}
          fill={`url(#${uid}-glow)`}
          opacity={s.glow}
        />
      )}

      <ellipse
        className="temu__shadow"
        cx={cx}
        cy={GROUND_Y + 5}
        rx={w * 0.36}
        ry={h * 0.05}
        fill={p.deep}
        opacity="0.16"
      />

      <g transform={`translate(${cx} ${GROUND_Y}) scale(${fit}) translate(${-cx} ${-GROUND_Y})`}>
      {isSpark ? (
        <Spark cx={cx} cy={cy} palette={p} />
      ) : (
        <>
          {s.roots && <Roots cx={cx} y={bottom} w={w} colour={p.body} />}

          {/* The whole body leans and breathes as one group, so nothing drifts. */}
          <g
            className="temu__body"
            style={{ transformOrigin: `${cx}px ${GROUND_Y}px`, transform: `rotate(${s.lean}deg)` }}
          >
            {s.leg > 0 && <Legs cx={cx} top={bottom} len={s.leg} w={w} colour={p.body} />}

            <Crest
              kind={s.crown}
              cx={cx}
              baseY={top + h * 0.05}
              height={s.crest}
              spread={s.crestSpread}
              fronds={s.fronds}
              fill={`url(#${uid}-crest)`}
              tip={p.highlight}
            />

            <SideLeaves cx={cx} cy={top + h * 0.46} w={w} count={s.sideLeaf} fill={`url(#${uid}-crest)`} />

            <path d={bodyPath(s.form, cx, top, w, h)} fill={`url(#${uid}-body)`} />
            <Shine cx={cx} top={top} w={w} h={h} />
            <FlourishMark kind={s.flourish ?? 'none'} cx={cx} cy={cy} w={w} h={h} colour={p.accent} deep={p.deep} />

            {s.arm > 0 && <Arms cx={cx} cy={cy + h * 0.06} w={w} len={s.arm} colour={p.body} />}

            {faceRx > 2 && (
              <ellipse cx={cx} cy={faceCy} rx={faceRx * 1.06} ry={faceRy * 1.06} fill={`url(#${uid}-face)`} opacity="0.92" />
            )}

            <g className="temu__face">
              <EyePair shape={face.eyes} cx={cx} cy={eyeCy} dx={eyeDx} r={eyeR} accent={p.deep} />
              <MouthShape shape={face.mouth} cx={cx} cy={mouthCy} scale={faceRx * 0.3} accent={p.deep} />
              <BlushPair
                shape={face.blush}
                cx={cx}
                cy={eyeCy + faceRy * 0.3}
                dx={faceRx * 0.68}
                r={eyeR}
                colour={BLUSH}
              />
            </g>

            {pulse && faceRx > 2 && (
              <PulseMark cx={cx} cy={faceCy + faceRy + h * 0.06} r={h * 0.06} pulse={pulse} colour={p.accent} />
            )}

          </g>

          {s.motes > 0 && <Motes cx={cx} cy={cy} r={w * 0.82} count={s.motes} colour={p.accent} />}
        </>
      )}
      </g>
    </svg>
  )
}

/**
 * The body outline, one per life stage.
 *
 * There used to be exactly one path — an asymmetric bean — so every stage was
 * that bean at a different size. Growing up is a change of shape, not a change
 * of scale: a seed is narrow on top and heavy at the bottom, a sprout is a
 * teardrop, an adult is a bean, and the late stages settle into something round
 * and sturdy. All five keep the same flat-ish base so Temu always sits rather
 * than floats.
 */
function bodyPath(form: BodyForm, cx: number, top: number, w: number, h: number): string {
  const hw = w / 2
  const l = cx - hw
  const r = cx + hw
  const bottom = top + h
  // Shoulder pinch: how far in the outline starts at the top. Small = round
  // head, large = narrow top with the mass carried low.
  const pinch = { seed: 0.66, drop: 0.88, bean: 0.3, pear: 0.52, round: 0.04 }[form]
  // Where the widest point sits. Low = pear, middle = bean, high = round.
  const waist = { seed: 0.72, drop: 0.7, bean: 0.5, pear: 0.7, round: 0.46 }[form]
  const tx = hw * (1 - pinch)
  const wy = top + h * waist
  return [
    `M ${cx} ${top}`,
    `C ${cx + tx} ${top}, ${r} ${top + h * waist * 0.45}, ${r} ${wy}`,
    `C ${r} ${bottom - h * 0.1}, ${cx + hw * 0.66} ${bottom}, ${cx} ${bottom}`,
    `C ${cx - hw * 0.62} ${bottom}, ${l} ${bottom - h * 0.08}, ${l} ${wy - h * 0.02}`,
    `C ${l} ${top + h * waist * 0.42}, ${cx - tx * 1.06} ${top}, ${cx} ${top}`,
    'Z',
  ].join(' ')
}

/** The gloss. One soft highlight is most of what makes a shape look plump. */
function Shine({ cx, top, w, h }: { cx: number; top: number; w: number; h: number }) {
  return (
    <ellipse
      className="temu__shine"
      cx={cx - w * 0.2}
      cy={top + h * 0.2}
      rx={w * 0.14}
      ry={h * 0.085}
      fill="#fff"
      opacity="0.22"
      transform={`rotate(-24 ${cx - w * 0.2} ${top + h * 0.2})`}
    />
  )
}

/** Four bold, tiny details make the journey legible between named chapters. */
function FlourishMark({
  kind,
  cx,
  cy,
  w,
  h,
  colour,
  deep,
}: {
  kind: NonNullable<StageShape['flourish']>
  cx: number
  cy: number
  w: number
  h: number
  colour: string
  deep: string
}) {
  if (kind === 'none') return null
  if (kind === 'freckles') {
    return (
      <g className="temu__flourish" fill={colour} opacity="0.72">
        {[-1, 1].flatMap((dir) => [0, 1].map((row) => (
          <circle key={`${dir}-${row}`} cx={cx + dir * w * (0.29 + row * 0.055)} cy={cy + h * (0.2 + row * 0.08)} r={Math.max(1.4, h * 0.021)} />
        )))}
      </g>
    )
  }
  if (kind === 'woven') {
    return (
      <g className="temu__flourish" fill="none" stroke={colour} strokeWidth={Math.max(2.2, h * 0.035)} strokeLinecap="round" opacity="0.82">
        <path d={`M ${cx - w * 0.34} ${cy + h * 0.25} Q ${cx} ${cy + h * 0.43}, ${cx + w * 0.34} ${cy + h * 0.19}`} />
        <path d={`M ${cx - w * 0.3} ${cy + h * 0.31} Q ${cx} ${cy + h * 0.48}, ${cx + w * 0.31} ${cy + h * 0.25}`} opacity="0.55" />
      </g>
    )
  }
  if (kind === 'mote') {
    return (
      <g className="temu__flourish temu__flourish--mote">
        <circle cx={cx + w * 0.56} cy={cy - h * 0.28} r={Math.max(3, h * 0.045)} fill={colour} />
        <circle cx={cx + w * 0.56} cy={cy - h * 0.28} r={Math.max(1.2, h * 0.018)} fill="#fff" opacity="0.86" />
      </g>
    )
  }
  return (
    <g className="temu__flourish" fill={colour} stroke={deep} strokeWidth={Math.max(0.8, h * 0.012)} opacity="0.86">
      {[-1, 1].map((dir) => (
        <path key={dir} d={`M ${cx + dir * w * 0.42} ${cy + h * 0.12} q ${dir * w * 0.2} ${-h * 0.13}, ${dir * w * 0.24} ${h * 0.04} q ${-dir * w * 0.12} ${h * 0.13}, ${-dir * w * 0.24} ${-h * 0.04} Z`} />
      ))}
    </g>
  )
}

/** Leaves on the body, one pair per `count`. Only the middle stages have them. */
function SideLeaves({
  cx,
  cy,
  w,
  count,
  fill,
}: {
  cx: number
  cy: number
  w: number
  count: number
  fill: string
}) {
  if (count <= 0) return null
  const len = w * 0.27
  return (
    <g className="temu__sideleaf" fill={fill} opacity="0.95">
      {Array.from({ length: count }, (_, i) => {
        const y = cy + i * len * 0.62
        const leaf = (dir: 1 | -1) => (
          <path
            key={dir}
            d={`M ${cx + dir * w * 0.44} ${y} q ${dir * len * 0.72} ${-len * 0.34}, ${dir * len * 1.05} ${len * 0.16} q ${-dir * len * 0.42} ${len * 0.5}, ${-dir * len * 1.05} ${-len * 0.16} Z`}
          />
        )
        return <g key={i}>{leaf(1)}{leaf(-1)}</g>
      })}
    </g>
  )
}

/**
 * What grows out of Temu's head.
 *
 * The mark is still "two things that meet", but it is a different drawing at
 * every stage of life rather than the same fan resized: a bare sprout, a closed
 * bud, a pair of leaves, an open fan, and finally a flower. Frond count only
 * matters to the kinds that fan out.
 */
function Crest({
  kind,
  cx,
  baseY,
  height,
  spread,
  fronds,
  fill,
  tip,
}: {
  kind: CrownKind
  cx: number
  baseY: number
  height: number
  spread: number
  fronds: number
  fill: string
  tip: string
}) {
  if (kind === 'none' || height <= 1) return null
  const stemW = Math.max(2, height * 0.13)

  /** One symmetric leaf on the centre line, rotated into place by the caller. */
  const leaf = (h: number, fw: number) =>
    [
      `M ${cx} ${baseY}`,
      `C ${cx + fw * 0.62} ${baseY - h * 0.3}, ${cx + fw * 0.44} ${baseY - h * 0.78}, ${cx} ${baseY - h}`,
      `C ${cx - fw * 0.44} ${baseY - h * 0.78}, ${cx - fw * 0.62} ${baseY - h * 0.3}, ${cx} ${baseY}`,
      'Z',
    ].join(' ')

  const stem = (
    <path
      d={`M ${cx} ${baseY} q ${-stemW * 0.3} ${-height * 0.4}, 0 ${-height * 0.6}`}
      fill="none"
      stroke={fill}
      strokeWidth={stemW}
      strokeLinecap="round"
    />
  )

  const parts = () => {
    switch (kind) {
      // One shoot, leaning, with a single leaf. What a seed does first.
      case 'sprout':
        return (
          <>
            {stem}
            <g transform={`rotate(26 ${cx} ${baseY})`}>
              <path d={leaf(height * 0.62, spread * 0.5)} fill={fill} />
            </g>
          </>
        )
      // A closed bud on a stalk — the shape right before it opens.
      case 'bud':
        return (
          <>
            {stem}
            <ellipse
              cx={cx}
              cy={baseY - height * 0.82}
              rx={spread * 0.3}
              ry={height * 0.34}
              fill={fill}
            />
            <circle cx={cx} cy={baseY - height * 1.05} r={stemW * 0.6} fill={tip} />
          </>
        )
      // Two leaves opening away from each other. The mark, at its simplest.
      case 'leaves':
        return (
          <>
            {stem}
            {[-1, 1].map((dir) => (
              <g key={dir} transform={`rotate(${dir * 34} ${cx} ${baseY})`}>
                <path d={leaf(height * 0.86, spread * 0.52)} fill={fill} opacity={dir === 1 ? 1 : 0.9} />
              </g>
            ))}
          </>
        )
      // A flower: petals all the way round a bright centre.
      case 'bloom': {
        const petals = Math.max(5, fronds)
        // Petal count is the late-stage clock: five when it first opens, nine by `abadi`.
        const pr = spread * 0.34
        const cyF = baseY - height * 0.56
        return (
          <>
            {stem}
            <g>
              {Array.from({ length: petals }, (_, i) => (
                <ellipse
                  key={i}
                  cx={cx}
                  cy={cyF - pr * 0.86}
                  rx={pr * 0.52}
                  ry={pr * 0.9}
                  fill={fill}
                  opacity={i % 2 ? 0.92 : 1}
                  transform={`rotate(${(i / petals) * 360} ${cx} ${cyF})`}
                />
              ))}
              <circle cx={cx} cy={cyF} r={pr * 0.56} fill={tip} />
            </g>
          </>
        )
      }
      // The open fan. Outer fronds are shorter, so the crown is rounded on top.
      default: {
        const open = Math.min(30 + fronds * 9, 84)
        const fw = Math.max(4, Math.min(height * 0.5, spread / Math.max(fronds, 1) + height * 0.16))
        return (
          <>
            {Array.from({ length: fronds }, (_, i) => {
              const t = fronds === 1 ? 0 : (i / (fronds - 1)) * 2 - 1 // -1 … 1
              const h = height * (1 - Math.abs(t) * 0.26)
              return (
                <g key={i} transform={`rotate(${(t * open) / 2} ${cx} ${baseY})`}>
                  <path
                    className={i % 2 === 0 ? 'temu__crest-a' : 'temu__crest-b'}
                    d={leaf(h, fw)}
                    fill={fill}
                    opacity={Math.abs(t) > 0.6 ? 0.86 : 1}
                  />
                  {height > 16 && <circle cx={cx} cy={baseY - h} r={Math.max(2, fw * 0.2)} fill={tip} />}
                </g>
              )
            })}
          </>
        )
      }
    }
  }

  return (
    <g className="temu__crest" style={{ transformOrigin: `${cx}px ${baseY}px` }}>
      {parts()}
    </g>
  )
}

/** Short, thick, rounded. Thin sticks made the earlier version look brittle. */
function Arms({ cx, cy, w, len, colour }: { cx: number; cy: number; w: number; len: number; colour: string }) {
  const width = Math.max(4.2, len * 0.3)
  return (
    <g className="temu__arms" fill="none" stroke={colour} strokeWidth={width} strokeLinecap="round">
      <path className="temu__arm temu__arm--l" d={`M ${cx - w * 0.4} ${cy} q ${-len * 0.5} ${len * 0.16}, ${-len * 0.66} ${len * 0.5}`} />
      <path className="temu__arm temu__arm--r" d={`M ${cx + w * 0.4} ${cy} q ${len * 0.5} ${len * 0.16}, ${len * 0.66} ${len * 0.5}`} />
    </g>
  )
}

function Legs({ cx, top, len, w, colour }: { cx: number; top: number; len: number; w: number; colour: string }) {
  const width = Math.max(5.5, len * 0.62)
  return (
    <g stroke={colour} strokeWidth={width} strokeLinecap="round">
      <line x1={cx - w * 0.17} y1={top - 1} x2={cx - w * 0.19} y2={top + len} />
      <line x1={cx + w * 0.17} y1={top - 1} x2={cx + w * 0.19} y2={top + len} />
    </g>
  )
}

function EyePair({
  shape,
  cx,
  cy,
  dx,
  r,
  accent,
}: {
  shape: Eyes
  cx: number
  cy: number
  dx: number
  r: number
  accent: string
}) {
  // Both eyes always match. Asymmetry at rest reads as a rendering bug.
  const one = (x: number, mirror: number) => {
    switch (shape) {
      case 'arc':
        return <path d={`M ${x - r} ${cy + r * 0.3} q ${r} ${-r * 1.25}, ${r * 2} 0`} fill="none" stroke={accent} strokeWidth={r * 0.62} strokeLinecap="round" />
      case 'sleepy':
        return <path d={`M ${x - r} ${cy} q ${r} ${r * 0.85}, ${r * 2} 0`} fill="none" stroke={accent} strokeWidth={r * 0.6} strokeLinecap="round" />
      case 'worried':
        return <path d={`M ${x - r} ${cy + r * 0.5} q ${r} ${-r * 0.7}, ${r * 2} ${r * 0.1}`} fill="none" stroke={accent} strokeWidth={r * 0.58} strokeLinecap="round" />
      case 'wide':
        return (
          <>
            <ellipse cx={x} cy={cy} rx={r * 1.05} ry={r * 1.3} fill={accent} />
            <circle cx={x + r * 0.3} cy={cy - r * 0.45} r={r * 0.34} fill="#fff" />
          </>
        )
      case 'sparkle':
        return (
          <g>
            <path d={`M ${x} ${cy - r * 1.5} L ${x + r * 0.5} ${cy} L ${x} ${cy + r * 1.5} L ${x - r * 0.5} ${cy} Z`} fill={accent} />
            <path d={`M ${x - r * 1.5} ${cy} L ${x} ${cy - r * 0.5} L ${x + r * 1.5} ${cy} L ${x} ${cy + r * 0.5} Z`} fill={accent} />
          </g>
        )
      case 'side':
        return (
          <>
            <circle cx={x} cy={cy} r={r} fill={accent} />
            <circle cx={x + r * 0.34 * mirror} cy={cy - r * 0.2} r={r * 0.3} fill="#fff" />
          </>
        )
      default:
        return (
          <>
            <circle cx={x} cy={cy} r={r} fill={accent} />
            <circle cx={x + r * 0.3} cy={cy - r * 0.35} r={r * 0.28} fill="#fff" opacity="0.9" />
          </>
        )
    }
  }
  return (
    <g className="temu__eyes" data-eyes={shape} stroke="none">
      {one(cx - dx, 1)}
      {one(cx + dx, 1)}
    </g>
  )
}

function MouthShape({
  shape,
  cx,
  cy,
  scale,
  accent,
}: {
  shape: Mouth
  cx: number
  cy: number
  scale: number
  accent: string
}) {
  const sw = Math.max(1.4, scale * 0.36)
  const stroke = { fill: 'none', stroke: accent, strokeWidth: sw, strokeLinecap: 'round' as const }
  switch (shape) {
    case 'open':
      return <ellipse cx={cx} cy={cy + scale * 0.15} rx={scale * 0.62} ry={scale * 0.72} fill={accent} />
    case 'o':
      return <circle cx={cx} cy={cy + scale * 0.1} r={scale * 0.46} fill={accent} />
    case 'flat':
      return <line x1={cx - scale * 0.46} y1={cy} x2={cx + scale * 0.46} y2={cy} {...stroke} />
    case 'wavy':
      return <path d={`M ${cx - scale * 0.6} ${cy} q ${scale * 0.3} ${-scale * 0.4}, ${scale * 0.6} 0 t ${scale * 0.6} 0`} {...stroke} />
    case 'pout':
      return <path d={`M ${cx - scale * 0.34} ${cy + scale * 0.2} q ${scale * 0.34} ${-scale * 0.42}, ${scale * 0.68} 0`} {...stroke} />
    case 'laugh':
      return (
        <>
          <path d={`M ${cx - scale * 0.72} ${cy - scale * 0.1} a ${scale * 0.72} ${scale * 0.72} 0 0 0 ${scale * 1.44} 0 Z`} fill={accent} />
          <path d={`M ${cx - scale * 0.4} ${cy + scale * 0.42} q ${scale * 0.4} ${scale * 0.3}, ${scale * 0.8} 0`} fill={accent} opacity="0.85" />
        </>
      )
    default:
      return <path d={`M ${cx - scale * 0.5} ${cy - scale * 0.12} q ${scale * 0.5} ${scale * 0.6}, ${scale} 0`} {...stroke} />
  }
}

function BlushPair({
  shape,
  cx,
  cy,
  dx,
  r,
  colour,
}: {
  shape: Blush
  cx: number
  cy: number
  dx: number
  r: number
  colour: string
}) {
  if (shape === 'none') return null
  const o = shape === 'soft' ? 0.5 : 0.34
  const rr = shape === 'soft' ? r * 1.5 : r * 0.85
  return (
    <g fill={colour} opacity={o}>
      <ellipse cx={cx - dx} cy={cy} rx={rr} ry={rr * 0.68} />
      <ellipse cx={cx + dx} cy={cy} rx={rr} ry={rr * 0.68} />
    </g>
  )
}

/**
 * The day's pulse, worn on the chest. Two halves: one per partner.
 * Deliberately not on the face — Temu's mood never depends on whether someone
 * has done their part yet.
 */
function PulseMark({
  cx,
  cy,
  r,
  pulse,
  colour,
}: {
  cx: number
  cy: number
  r: number
  pulse: { a: boolean; b: boolean }
  colour: string
}) {
  const both = pulse.a && pulse.b
  return (
    <g className={`temu__pulse ${both ? 'temu__pulse--full' : ''}`}>
      <circle cx={cx} cy={cy} r={r} fill="#fff" opacity="0.28" />
      <path
        d={`M ${cx} ${cy - r} a ${r} ${r} 0 0 0 0 ${r * 2} Z`}
        fill={colour}
        opacity={pulse.a ? 0.95 : 0.16}
      />
      <path
        d={`M ${cx} ${cy - r} a ${r} ${r} 0 0 1 0 ${r * 2} Z`}
        fill={colour}
        opacity={pulse.b ? 0.95 : 0.16}
      />
    </g>
  )
}

/** One ring per year past the tenth stage. Growth that costs no new art. */

/** Memories in orbit, from the eleventh stage. */
function Motes({ cx, cy, r, count, colour }: { cx: number; cy: number; r: number; count: number; colour: string }) {
  return (
    <g className="temu__motes" style={{ transformOrigin: `${cx}px ${cy}px` }}>
      {Array.from({ length: count }, (_, i) => {
        const angle = (i / count) * Math.PI * 2
        return (
          <circle
            key={i}
            cx={cx + Math.cos(angle) * r}
            cy={cy + Math.sin(angle) * r * 0.42}
            r={2.6}
            fill={colour}
            opacity="0.8"
          />
        )
      })}
    </g>
  )
}

function Roots({ cx, y, w, colour }: { cx: number; y: number; w: number; colour: string }) {
  return (
    <g stroke={colour} strokeWidth="2.2" strokeLinecap="round" opacity="0.5" fill="none">
      <path d={`M ${cx - w * 0.2} ${y} q ${-w * 0.22} ${w * 0.1}, ${-w * 0.34} ${w * 0.05}`} />
      <path d={`M ${cx + w * 0.2} ${y} q ${w * 0.22} ${w * 0.1}, ${w * 0.34} ${w * 0.05}`} />
      <path d={`M ${cx} ${y} q ${-w * 0.05} ${w * 0.14}, ${-w * 0.14} ${w * 0.18}`} />
    </g>
  )
}

/** Stage 0 — before there is a body, there are just two sparks finding each other. */
function Spark({ cx, cy, palette }: { cx: number; cy: number; palette: { body: string; accent: string } }) {
  const flame = (x: number, fill: string, className: string, mirror: number) => (
    <g className={className}>
      <path
        d={`M ${x} ${cy - 43} C ${x + mirror * 4} ${cy - 29}, ${x + mirror * 18} ${cy - 20}, ${x + mirror * 17} ${cy - 3} C ${x + mirror * 16} ${cy + 17}, ${x - mirror * 16} ${cy + 18}, ${x - mirror * 17} ${cy - 3} C ${x - mirror * 15} ${cy - 18}, ${x - mirror * 4} ${cy - 26}, ${x} ${cy - 43} Z`}
        fill={fill}
      />
      <circle cx={x - 5} cy={cy - 5} r="2.2" fill="#7d3142" />
      <circle cx={x + 5} cy={cy - 5} r="2.2" fill="#7d3142" />
      <path d={`M ${x - 4} ${cy + 3} q 4 4, 8 0`} fill="none" stroke="#7d3142" strokeWidth="1.8" strokeLinecap="round" />
      <ellipse cx={x - 9} cy={cy + 1} rx="3" ry="2" fill="#f2708c" opacity="0.52" />
      <ellipse cx={x + 9} cy={cy + 1} rx="3" ry="2" fill="#f2708c" opacity="0.52" />
    </g>
  )
  return (
    <g className="temu__spark" transform="translate(100 147) scale(2.05) translate(-100 -160)">
      {flame(cx - 24, palette.body, 'temu__spark-a', -1)}
      {flame(cx + 24, palette.accent, 'temu__spark-b', 1)}
    </g>
  )
}

export type { StageShape }
